```css
.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}

.button-row .btn {
  font: inherit;
  font-size: clamp(0.9rem, 0.8rem + 0.4vw, 1.05rem);
  line-height: 1.2;
  padding: 0.6em 1.2em;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.button-row .btn:focus-visible {
  outline: 3px solid var(--cresyl);
  outline-offset: 3px;
}

/* Primary: solid accent fill, text on it uses --slide */
.button-row .btn-primary {
  background: var(--myelin);
  border-color: var(--myelin);
  color: var(--slide);
}

.button-row .btn-primary:hover:not(:disabled) {
  border-color: var(--ink);
}

/* Secondary: outlined */
.button-row .btn-secondary {
  border-color: var(--ink);
  color: var(--ink);
}

.button-row .btn-secondary:hover:not(:disabled) {
  background: var(--myelin-wash);
}

/* Quiet: text only, underlined so it still reads as a control */
.button-row .btn-quiet {
  padding-inline: 0.4em;
  color: var(--ink);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.25em;
}

.button-row .btn-quiet:hover:not(:disabled) {
  text-decoration-thickness: 2px;
}

/* Disabled: muted text and outline, no fill; no opacity so text keeps its token colour */
.button-row .btn:disabled {
  cursor: not-allowed;
  background: transparent;
  color: var(--muted);
  border-color: var(--muted);
}

.button-row .btn-quiet:disabled {
  border-color: transparent;
  text-decoration: none;
}

:root[data-motion="reduce"] .button-row .btn {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .button-row .btn {
    transition: none;
  }
}
